#!/bin/bash
# The feature-completion APKs, all UNSIGNED (no keystore is read or created):
#   1. the agent bundle (standalone/build-bundle.mjs) from the tree
#   2. classes.dex (build.sh step 3: javac --release 17 vs android-35 + 32 slot classes, d8 --min-api 34) for the tree, and
#      the tree + the phone-dns-recovery RelayDial patch (composed), as the frozen candidate offered
#   3. the INSTALLED APK with exactly these entries replaced or added (everything else byte for byte: manifest, resources,
#      build.json, idle-app.wasm, libnode.so, libenclavewg.so, libc++_shared.so):
#        classes.dex, assets/agent/{standalone,net-child,windows-circuit-worker,adb-self}.mjs,
#        lib/arm64-v8a/libanchor.so (the measured payload), lib/arm64-v8a/libpvmcustody.so (new); libpvm_rt.so stays the
#        INSTALLED bytes (this work leaves runtime/pvm-rt unchanged)
#      stored uncompressed and aligned as build.sh aligns them (zipalign -P 16 -f 4)
# Needs build-native.sh payload and custody first (artifacts/native/).
set -euo pipefail
H=/home/steven/Documents/Codex/2026-10-18/wo/work/android-feature-completion; P=/home/steven/Documents/Codex/2026-10-18/wo/work/phone-dns-recovery
SDK=/home/steven/Android/Sdk; BT=$SDK/build-tools/35.0.0; AJ=$SDK/platforms/android-35/android.jar
O=$H/artifacts; N=$O/native; INSTALLED=$P/claude/installed-host.apk
for f in $N/payload-candidate/libanchor.so $N/libpvmcustody.so; do [ -f $f ] || { echo "missing $f (run build-native.sh first)"; exit 2; }; done
rm -rf $O/bundle-feature $O/dex-feature* $O/apk-feature*; mkdir -p $O
IDLE=$(mktemp -d)/idle-app.wasm; python3 -c "import zipfile,sys;open(sys.argv[2],'wb').write(zipfile.ZipFile(sys.argv[1]).read('assets/agent/idle-app.wasm'))" $INSTALLED $IDLE
(cd $H/tree && node shielded/anchor/avf/standalone/build-bundle.mjs $O/bundle-feature $IDLE) > $O/bundle-feature.log 2>&1 || { echo "bundle FAILED"; cat $O/bundle-feature.log; exit 1; }
echo "bundle feature: exit 0"; sed 's/^/   /' $O/bundle-feature.log
dexof() {   # <name> <host/app dir>
  local S=$O/dex-$1; mkdir -p $S/classes $S/dex $S/gen
  for k in $(seq 1 32); do printf '/* generated by build.sh: slot %s, its own process (":slot%s") */\npackage host.enclave.anchor.avf;\npublic class AnchorServiceSlot%s extends AnchorService { }\n' "$k" "$k" "$k" > $S/gen/AnchorServiceSlot$k.java; done
  javac --release 17 -Xlint:-options -cp "$AJ" -d $S/classes $2/*.java $S/gen/*.java > $S/javac.log 2>&1 || { echo "$1: javac FAILED"; cat $S/javac.log; exit 1; }
  "$BT/d8" --min-api 34 --output $S/dex $S/classes/host/enclave/anchor/avf/*.class > $S/d8.log 2>&1 || { echo "$1: d8 FAILED"; cat $S/d8.log; exit 1; }
  echo "dex $1: javac+d8 exit 0, classes.dex $(sha256sum $S/dex/classes.dex | cut -c1-64) ($(stat -c %s $S/dex/classes.dex) B)"
}
dexof feature $H/tree/shielded/anchor/avf/host/app
C=$(mktemp -d); trap 'rm -rf $C' EXIT; mkdir -p $C/x/shielded/anchor/avf/host && cp -r $H/tree/shielded/anchor/avf/host/app $C/x/shielded/anchor/avf/host/app
( cd $C/x && patch -s -p1 < $P/claude/host-relaydial.patch ) || { echo "the RelayDial patch does not apply on the feature tree"; exit 1; }
echo "   RelayDial patch (phone-dns-recovery, $(sha256sum $P/claude/host-relaydial.patch | cut -c1-16)) applies cleanly"
dexof feature-relaydial $C/x/shielded/anchor/avf/host/app
for v in feature feature-relaydial; do
  python3 - "$O" "$v" "$INSTALLED" <<'PY'
import sys, zipfile, hashlib
O, v, inst = sys.argv[1], sys.argv[2], sys.argv[3]
src = zipfile.ZipFile(inst)
N = f'{O}/native'
repl = {'classes.dex': open(f'{O}/dex-{v}/dex/classes.dex', 'rb').read(),
        'lib/arm64-v8a/libanchor.so': open(f'{N}/payload-candidate/libanchor.so', 'rb').read()}
for f in ['standalone.mjs', 'net-child.mjs', 'windows-circuit-worker.mjs', 'adb-self.mjs']:
    repl[f'assets/agent/{f}'] = open(f'{O}/bundle-feature/{f}', 'rb').read()
add = {'lib/arm64-v8a/libpvmcustody.so': open(f'{N}/libpvmcustody.so', 'rb').read()}
dst = zipfile.ZipFile(f'{O}/apk-{v}-unaligned.apk', 'w')
last_lib = None
names = [i.filename for i in src.infolist()]
for i in src.infolist():
    if i.filename.startswith('META-INF/') and i.filename.rsplit('.', 1)[-1] in ('SF', 'RSA', 'EC', 'DSA', 'MF'): continue
    data = repl.get(i.filename, src.read(i))
    zi = zipfile.ZipInfo(i.filename, date_time=i.date_time); zi.external_attr = i.external_attr
    dst.writestr(zi, data, compress_type=i.compress_type)
    if i.filename == 'lib/arm64-v8a/libpvm_rt.so':   # the new library right after its sibling, stored like it
        for n, b in add.items():
            z2 = zipfile.ZipInfo(n, date_time=i.date_time); z2.external_attr = i.external_attr
            dst.writestr(z2, b, compress_type=zipfile.ZIP_STORED)
dst.close()
a, b = zipfile.ZipFile(inst), zipfile.ZipFile(f'{O}/apk-{v}-unaligned.apk')
ha = {i.filename: hashlib.sha256(a.read(i)).hexdigest() for i in a.infolist() if not i.filename.startswith('META-INF/')}
hb = {i.filename: hashlib.sha256(b.read(i)).hexdigest() for i in b.infolist()}
diff = sorted(n for n in set(ha) | set(hb) if ha.get(n) != hb.get(n))
assert set(diff) <= set(repl) | set(add), diff
print(f'apk {v}: entries changed or added vs installed: {diff}')
PY
  "$BT/zipalign" -P 16 -f 4 $O/apk-$v-unaligned.apk $O/apk-$v-unsigned.apk && "$BT/zipalign" -c -P 16 4 $O/apk-$v-unsigned.apk && rm $O/apk-$v-unaligned.apk
  echo "   apk-$v-unsigned.apk $(sha256sum $O/apk-$v-unsigned.apk | cut -c1-64) (zipalign -c -P 16 4: ok; NOT signed)"
done
echo "ALL APK BUILDS DONE"
